import Image from "next/image";
import Link from "next/link";
import { site } from "@/config/site";
import { cn } from "@/lib/cn";

/**
 * Official UPos logo (mark + wordmark). Files are generated by scripts/build_brand_assets.py
 * from assets/brand/upos-logo-source.webp — re-run it instead of editing the PNGs.
 * tone="default": brand colours, with a recoloured copy for dark mode (only the visible one
 * is downloaded; the hidden one stays lazy and display:none).
 * tone="onBrand": white, for the green footer.
 */
const LOGO_WIDTH = 405;
const LOGO_HEIGHT = 240;

type LogoProps = { className?: string; imageClassName?: string; tone?: "default" | "onBrand" };

export function Logo({ className, imageClassName, tone = "default" }: LogoProps) {
  const imgClass = cn("h-10 w-auto lg:h-12", imageClassName);
  const image = (src: string, extra?: string) => (
    <Image src={src} alt="" width={LOGO_WIDTH} height={LOGO_HEIGHT} sizes="96px" className={cn(imgClass, extra)} />
  );

  return (
    <Link
      href="/"
      aria-label={`${site.name} home`}
      className={cn("inline-flex shrink-0 items-center rounded-lg", className)}
    >
      {tone === "onBrand" ? (
        image("/brand/upos-logo-white.png")
      ) : (
        <>
          {image("/brand/upos-logo.png", "dark:hidden")}
          {image("/brand/upos-logo-dark.png", "hidden dark:block")}
        </>
      )}
    </Link>
  );
}
